+const page = await context.newPage();
+const errors = [], externalRequests = [], results = [];
+page.on('pageerror',error=>errors.push(error.message));
+page.on('request',request=>{ if (/^https?:/.test(request.url())) externalRequests.push(request.url()); });
+await page.goto(url);
+
+// Test the visible bowl, not the deliberately oversized SVG's empty margins.
+for (const [width,height] of [[1440,900],[390,844],[320,568],[768,1024],[844,390],[2560,1440]]) {
+  await page.setViewportSize({width,height});
+  await page.waitForTimeout(120);
+  const geometry = await page.evaluate(() => {
+    const rect = document.querySelector('.scene').getBoundingClientRect();
+    return {
+      scrollWidth:document.documentElement.scrollWidth,
+      scrollHeight:document.documentElement.scrollHeight,
+      center:rect.left+rect.width/2,
+      bowlLeft:rect.left+rect.width*242/1200,
+      bowlRight:rect.left+rect.width*958/1200,
+      bowlTop:rect.top+rect.height*290/1000,
+      bowlBottom:rect.top+rect.height*850/1000,
+      visibleText:document.body.innerText.trim(),
+      controls:document.querySelectorAll('button,input,select,textarea,nav,menu').length,
+    };
+  });
+  assert.equal(geometry.scrollWidth,width,`horizontal overflow at ${width}x${height}`);
+  assert.equal(geometry.scrollHeight,height,`vertical overflow at ${width}x${height}`);
+  assert.ok(Math.abs(geometry.center-width/2)<1,`not centered at ${width}x${height}`);
+  assert.ok(geometry.bowlLeft>=0 && geometry.bowlRight<=width && geometry.bowlTop>=0 && geometry.bowlBottom<=height,`bowl clipped at ${width}x${height}: ${JSON.stringify(geometry)}`);
+  assert.equal(geometry.visibleText,'');
+  assert.equal(geometry.controls,0);
+  results.push(`layout ${width}×${height}: centered, unclipped, no scrolling or UI`);
+  if (width===1440 || width===390 || width===844) await page.screenshot({path:`<TMP>/ramen-final-${width}.png`});
+}
+
+await page.setViewportSize({width:1440,height:900});
+await page.waitForTimeout(100);
+const steamA = await page.locator('canvas').evaluate(el=>el.toDataURL());
+await page.waitForTimeout(600);
+const steamB = await page.locator('canvas').evaluate(el=>el.toDataURL());
